{panel:bgColor=#deebff}
h3. Context
* {{src/ci.ts:4}} {{getBuild}} The CI build request has no timeout or abort signal, so a stalled CI response hangs every caller of {{getBuild}}.
{panel}

h3. Details
Paths and line numbers refer to commit {{4ef35ce0077924f16ca19a77c0823a644f521bb3}} on main.

{code:javascript}
// src/ci.ts:2-7

export async function getBuild(id: string): Promise<unknown> {
  const res = await fetch(`${CI}/builds/${id}`);
  return res.json();
}

{code}
